// Preloaded into `next start` for measurement only: logs every outbound fetch (Supabase/PostgREST) with timing.
const fs = require("node:fs");
const out = process.env.FETCH_LOG || ".qa/perf/fetch.log";
const original = globalThis.fetch;
globalThis.fetch = async function (input, init) {
  const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
  const start = Date.now();
  try { return await original.call(this, input, init); }
  finally {
    if (!url.startsWith("http://localhost") && !url.startsWith("http://127.")) {
      const u = new URL(url);
      fs.appendFileSync(out, JSON.stringify({ start, dur: Date.now() - start, method: init?.method ?? (typeof input === "object" && input.method) ?? "GET", path: u.pathname, q: u.search.slice(0, 160) }) + "\n");
    }
  }
};
