import postgres from "postgres";
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [user] = await db`select id, raw_user_meta_data->>'qa_test' qa from auth.users where email=${process.env.E2E_USER_EMAIL}`;
if (user?.qa !== "e2e-auth") throw new Error("Not the QA user");
const [ws] = await db`select id from public.workspaces where owner_id=${user.id}`;
if (process.argv.includes("--remove")) {
  const r = await db`delete from public.transactions where workspace_id=${ws.id} and 'perf-seed' = any(tags)`;
  console.log("removed", r.count); await db.end(); process.exit(0);
}
const accounts = await db`select id, currency_code from public.accounts where workspace_id=${ws.id} and archived_at is null`;
const categories = await db`select id from public.categories where workspace_id=${ws.id}`;
const merchants = await db`select id from public.merchants where workspace_id=${ws.id}`;
console.log({ accounts: accounts.length, categories: categories.length, merchants: merchants.length });
let seed = 42; const rand = () => (seed = (seed * 1103515245 + 12345) % 2 ** 31) / 2 ** 31;
const pick = xs => xs[Math.floor(rand() * xs.length)];
const rows = [];
const today = new Date("2026-10-26T00:00:00Z");
for (let i = 0; i < 2000; i++) {
  const account = accounts[i % accounts.length];
  const day = new Date(today.getTime() - Math.floor(rand() * 540) * 86400000).toISOString().slice(0, 10);
  const income = rand() < 0.08;
  const amount = income ? BigInt(50000 + Math.floor(rand() * 300000)) : -BigInt(100 + Math.floor(rand() * 15000));
  rows.push({ workspace_id: ws.id, account_id: account.id, posted_on: day, description: `${income ? "Payroll" : pick(["Grocer", "Cafe", "Transit", "Pharmacy", "Bookshop", "Utilities", "Streaming", "Restaurant"])} ${i}`,
    amount_minor: amount.toString(), currency_code: account.currency_code, tags: ["perf-seed"],
    category_id: rand() < 0.3 ? null : pick(categories).id, merchant_id: rand() < 0.4 || !merchants.length ? null : pick(merchants).id });
}
for (let i = 0; i < rows.length; i += 500) await db`insert into public.transactions ${db(rows.slice(i, i + 500))}`;
console.log("inserted", rows.length);
await db.end();

