// Prints server fetch waterfalls from fetch.log, splitting requests on idle gaps > 400 ms.
// Usage: node .qa/perf/waterfall.mjs [log] [maxBursts]
import fs from "node:fs";
const rows = fs.readFileSync(process.argv[2] ?? ".qa/perf/fetch.log", "utf8").split("\n").filter(Boolean).map(JSON.parse).sort((a, b) => a.start - b.start);
const bursts = []; let cur = null, end = 0;
for (const r of rows) { if (!cur || r.start > end + 400) bursts.push(cur = []); cur.push(r); end = Math.max(end, r.start + r.dur); }
for (const b of bursts.slice(0, Number(process.argv[3] ?? 99))) {
  const t0 = b[0].start, last = Math.max(...b.map(r => r.start + r.dur));
  console.log(`--- ${b.length} fetches, ${last - t0} ms wall, ${b.reduce((s, r) => s + r.dur, 0)} ms summed`);
  for (const r of b) console.log(String(r.start - t0).padStart(5), String(r.dur).padStart(5), r.method, r.path.replace("/rest/v1/", ""), r.q.slice(0, 110));
}

