// Read-only timing of the balance-evidence transactions read at different page sizes (service role, QA workspace only).
import { createClient } from "@supabase/supabase-js";
import postgres from "postgres";
const sql = postgres(process.env.SUPABASE_DB_URL, { max: 1 });
const [u] = await sql`select id from auth.users where email=${process.env.E2E_USER_EMAIL}`;
const [w] = await sql`select id from public.workspaces where owner_id=${u.id}`;
await sql.end();
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false } });
const cols = "id, account_id, amount_minor::text, currency_code, posted_on, posted_at, status, version, description, kind, review_reasons, transaction_sources(source_transaction_id)";
const time = async (fn) => { const t = Date.now(); await fn(); return Date.now() - t; };
const median = xs => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)];
const page = (from, to, count) => db.from("transactions").select(cols, count ? { count } : undefined).eq("workspace_id", w.id).order("id").range(from, to);
const results = { p500: [], p1000: [], head: [], allSeq500: [], allPar500: [], allPar1000: [] };
for (let i = 0; i < 7; i++) {
  results.p500.push(await time(() => page(0, 499, "exact")));
  results.p1000.push(await time(() => page(0, 999, "exact")));
  results.head.push(await time(() => db.from("transactions").select("id", { count: "exact", head: true }).eq("workspace_id", w.id)));
  results.allSeq500.push(await time(async () => { for (let o = 0; ; o += 500) { const { data } = await page(o, o + 499); if (data.length < 500) break; } }));
  results.allPar500.push(await time(async () => { const f = await page(0, 499, "exact"); await Promise.all(Array.from({ length: Math.ceil(f.count / 500) - 1 }, (_, k) => page((k + 1) * 500, (k + 2) * 500 - 1))); }));
  results.allPar1000.push(await time(async () => { const f = await page(0, 999, "exact"); await Promise.all(Array.from({ length: Math.ceil(f.count / 1000) - 1 }, (_, k) => page((k + 1) * 1000, (k + 2) * 1000 - 1))); }));
}
console.log(Object.fromEntries(Object.entries(results).map(([k, v]) => [k, median(v)])));

