// Markdown before/after tables from before.json and after.json (medians of 5 runs).
import fs from "node:fs";
const before = JSON.parse(fs.readFileSync(".qa/perf/before.json", "utf8")), after = JSON.parse(fs.readFileSync(".qa/perf/after.json", "utf8"));
const ms = v => v == null ? "—" : `${Math.round(v).toLocaleString("en")} ms`;
const pct = (b, a) => b == null || a == null || !b ? "—" : `${a <= b ? "−" : "+"}${Math.abs(Math.round((b - a) * 100 / b))}%`;
const row = cells => `| ${cells.join(" | ")} |`;
const out = [];
out.push("### Hard page loads (signed in, data fully rendered)", "", row(["Route", "Ready before", "Ready after", "Change", "LCP before → after", "Server fetches before → after"]), row(["---", "---:", "---:", "---:", "---:", "---:"]));
for (const [k, b] of Object.entries(before.hard)) { const a = after.hard[k] ?? {}; out.push(row([`\`${k}\``, ms(b.ready), ms(a.ready), pct(b.ready, a.ready), `${ms(b.lcp)} → ${ms(a.lcp)}`, `${b.serverFetches} → ${a.serverFetches}`])); }
out.push("", "### Client navigations (click → new page's data rendered)", "", row(["Navigation", "Ready before", "Ready after", "Change", "Server fetches before → after"]), row(["---", "---:", "---:", "---:", "---:"]));
for (const [k, b] of Object.entries(before.nav)) { const a = after.nav[k] ?? {}; if (b.ready == null) continue; out.push(row([`Overview → \`${k}\``.replace("Overview → `/money/transactions -> ", "`/money/transactions -> ").replace(/Overview → `(\/[^`]+ -> )/, "`$1"), ms(b.ready), ms(a.ready), pct(b.ready, a.ready), `${b.serverFetches} → ${a.serverFetches}`])); }
out.push("", "### Interactions (click → content updated)", "", row(["Interaction", "Before", "After", "Change", "Server fetches before → after"]), row(["---", "---:", "---:", "---:", "---:"]));
for (const [k, b] of Object.entries(before.interactions)) { const a = after.interactions[k] ?? {}; if (b.ready == null) continue; out.push(row([k, ms(b.ready), ms(a.ready), pct(b.ready, a.ready), `${b.serverFetches} → ${a.serverFetches}`])); }
for (const flow of ["out", "in"]) {
  const b = before.workflow[flow], a = after.workflow[flow];
  out.push("", `### Workflow: Overview → Cash flow → ${flow === "out" ? "Out" : "In"} → Uncategorized`, "", row(["Step", "Before", "After", "Change", "Server fetches before → after"]), row(["---", "---:", "---:", "---:", "---:"]));
  out.push(row(["1. Open Overview (hard load, chart drawn)", ms(b.overview), ms(a.overview), pct(b.overview, a.overview), `${b.overviewFetches} → ${a.overviewFetches}`]));
  out.push(row(["2. Scroll to Cash flow", "0 ms (anchor)", "0 ms (anchor)", "—", "0 → 0"]));
  out.push(row([`3. Select ${flow === "out" ? "Out" : "In"} (breakdown shown)`, ms(b.selectFlow), ms(a.selectFlow), pct(b.selectFlow, a.selectFlow), `${b.selectFlowFetches} → ${a.selectFlowFetches}`]));
  out.push(row(["4. Open Uncategorized (filtered ledger shown)", ms(b.uncategorized), ms(a.uncategorized), pct(b.uncategorized, a.uncategorized), `${b.uncategorizedFetches} → ${a.uncategorizedFetches}`]));
  out.push(row(["**Total**", `**${ms(b.total)}**`, `**${ms(a.total)}**`, `**${pct(b.total, a.total)}**`, ""]));
}
out.push("", `Errors before: ${before.errors.length}, after: ${after.errors.length}. Console errors before: ${JSON.stringify(before.consoleErrors)}; after: ${JSON.stringify(after.consoleErrors)}`);
fs.writeFileSync(".qa/perf/report.md", out.join("\n"));
console.log(out.join("\n"));

