/** Net worth over time; hovering (or tapping) shows the exact amount and date at that point. */
export function NetWorthChart({ points, label }: { points: NetWorthPoint[]; label: string }) {
  const [active, setActive] = useState<number | null>(null);
  const gradient = useId();
  const values = points.map(point => point.y);
  const min = Math.min(...values), max = Math.max(...values), span = max - min || 1;
  const x = (index: number) => points.length === 1 ? WIDTH / 2 : (index / (points.length - 1)) * WIDTH;
  const y = (value: number) => HEIGHT - PAD - ((value - min) / span) * (HEIGHT - PAD * 2);
  const line = points.map((point, index) => `${x(index).toFixed(1)},${y(point.y).toFixed(1)}`).join(" ");
  const pick = (clientX: number, rect: DOMRect) => setActive(Math.max(0, Math.min(points.length - 1, Math.round(((clientX - rect.left) / rect.width) * (points.length - 1)))));
  const shown = active === null ? null : points[active];
  return <div className="relative" onPointerLeave={() => setActive(null)}>
    <svg role="img" aria-label={label} viewBox={`0 0 ${WIDTH} ${HEIGHT}`} preserveAspectRatio="none" className="h-[140px] w-full cursor-crosshair touch-none overflow-visible text-brand"
      onPointerMove={event => pick(event.clientX, event.currentTarget.getBoundingClientRect())} onPointerDown={event => pick(event.clientX, event.currentTarget.getBoundingClientRect())}>
      <defs><linearGradient id={gradient} x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity={0.22} /><stop offset="100%" stopColor="currentColor" stopOpacity={0} /></linearGradient></defs>
      <polygon points={`0,${HEIGHT} ${line} ${WIDTH},${HEIGHT}`} fill={`url(#${gradient})`} />
      <polyline points={line} fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
      {active !== null && <line x1={x(active)} x2={x(active)} y1={0} y2={HEIGHT} stroke="var(--color-muted-foreground)" strokeOpacity={0.5} strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />}
    </svg>
    {shown && <>
      <span aria-hidden="true" className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-card bg-brand shadow"
        style={{ left: `${(x(active!) / WIDTH) * 100}%`, top: `${(y(shown.y) / HEIGHT) * 100}%` }} />
      <div role="status" className="pointer-events-none absolute z-10 rounded-lg border border-border bg-card px-3 py-2 shadow-lg"
        style={{ left: `clamp(0px, calc(${(x(active!) / WIDTH) * 100}% - 4.5rem), calc(100% - 9rem))`, top: `max(0px, calc(${(y(shown.y) / HEIGHT) * 100}% - 4.75rem))` }}>
        <p className="whitespace-nowrap font-mono text-sm font-semibold">{shown.amount}</p>
        <p className="whitespace-nowrap text-[11px] text-muted-foreground">{shown.label}</p>
      </div>
    </>}
  </div>;
}
"use client";

import { ReactECharts, useThemeColors } from "@/components/chart";
import type { ModelUsage } from "@/lib/ai/usage";

// One horizontal bar per model, split into input and output tokens. Models are ordered largest first.
export function UsageChart({ models, locale }: { models: ModelUsage[]; locale: string }) {
  const colors = useThemeColors();
  const format = (value: number) => new Intl.NumberFormat(locale).format(value);
  const axis = { axisLine: { lineStyle: { color: colors.border } }, axisLabel: { color: colors.muted }, splitLine: { lineStyle: { color: colors.border, type: "dashed" } } };
  const segment = { barMaxWidth: 28, itemStyle: { borderColor: colors.card, borderWidth: 2 } };
  const summary = models.map(model => `${model.model_id}: ${format(model.input_tokens + model.output_tokens)} tokens`).join("; ");
  return (
    <div>
      <div role="img" aria-label={`Tokens per model. ${summary}`}>
        <ReactECharts
          style={{ height: Math.max(160, models.length * 56 + 64) }}
          option={{
            grid: { left: 8, right: 16, top: 40, bottom: 8, containLabel: true },
            legend: { top: 0, textStyle: { color: colors.muted } },
            tooltip: { trigger: "axis", axisPointer: { type: "shadow" }, valueFormatter: format },
            xAxis: { type: "value", ...axis, axisLabel: { color: colors.muted, formatter: format } },
            yAxis: { type: "category", inverse: true, data: models.map(model => model.model_id), ...axis },
            series: [
              { ...segment, name: "Input", type: "bar", stack: "tokens", data: models.map(model => model.input_tokens), color: colors.input },
              { ...segment, name: "Output", type: "bar", stack: "tokens", data: models.map(model => model.output_tokens), color: colors.output, itemStyle: { ...segment.itemStyle, borderRadius: [0, 4, 4, 0] } },
            ],
          }}
        />
      </div>
      <details className="mt-3 text-sm text-muted-foreground">
        <summary className="cursor-pointer">View as table</summary>
        <table className="mt-2 w-full text-left tabular-nums">
          <thead><tr className="border-b border-border"><th className="py-1.5 font-medium">Model</th><th className="py-1.5 text-right font-medium">Requests</th><th className="py-1.5 text-right font-medium">Input</th><th className="py-1.5 text-right font-medium">Output</th><th className="py-1.5 text-right font-medium">Total</th></tr></thead>
          <tbody>{models.map(model => <tr key={model.model_id} className="border-b border-border last:border-0">
            <th scope="row" className="py-1.5 font-normal break-all text-foreground">{model.model_id}</th>
            <td className="py-1.5 text-right">{format(model.requests)}</td>
            <td className="py-1.5 text-right">{format(model.input_tokens)}</td>
            <td className="py-1.5 text-right">{format(model.output_tokens)}</td>
            <td className="py-1.5 text-right">{format(model.input_tokens + model.output_tokens)}</td>
          </tr>)}</tbody>
        </table>
      </details>
    </div>
  );
}
  document.body.appendChild(probe);
  const color = getComputedStyle(probe).color;
  probe.remove();
  return color || fallback;
}

// Chart colors follow the app's CSS tokens, including the dark theme.
export function useThemeColors() {
  const theme = useSyncExternalStore(subscribeTheme, () => document.documentElement.dataset.theme ?? "light", () => "light");
  return useMemo(() => {
    const fallback = theme === "dark" ? { brand: "#cbf26b", muted: "#a3a39e", border: "#24262a", card: "#16171a", input: "#3987e5", output: "#d95926", out: "#5b5d62" } : { brand: "#4a6400", muted: "#5c5d58", border: "#e2e0d8", card: "#ffffff", input: "#2a78d6", output: "#eb6834", out: "#a9aaa3" };
    return { brand: token("--color-brand", fallback.brand), muted: token("--color-muted-foreground", fallback.muted), border: token("--color-border", fallback.border), card: token("--color-card", fallback.card), input: token("--color-chart-input", fallback.input), output: token("--color-chart-output", fallback.output), out: token("--color-chart-out", fallback.out) };
  }, [theme]);
}

export function SpendingChart({ values, labels, type = "bar", height = 280, ariaLabel, formatValue, onSelect }: {
  values: number[];
  labels?: string[];
  type?: "bar" | "line";
  height?: number;
  ariaLabel?: string;
  formatValue?: (value: number) => string;
  onSelect?: (index: number) => void;
}) {
  const colors = useThemeColors();
  const axis = { axisLine: { lineStyle: { color: colors.border } }, axisLabel: { color: colors.muted }, splitLine: { lineStyle: { color: colors.border, type: "dashed" } } };
  return (
    <div role={ariaLabel ? "img" : undefined} aria-label={ariaLabel}>
      <ReactECharts
        option={{
          color: [colors.brand],
          grid: { left: 8, right: 8, top: 16, bottom: 8, containLabel: true },
          tooltip: { trigger: "axis", ...(formatValue ? { valueFormatter: formatValue } : {}) },
          xAxis: { type: "category", data: labels ?? values.map((_, i) => `W${i + 1}`), ...axis },
          yAxis: { type: "value", ...axis, ...(formatValue ? { axisLabel: { color: colors.muted, formatter: formatValue } } : {}) },
          series: [{ type, data: values, ...(type === "line" ? { smooth: true, showSymbol: false, areaStyle: { opacity: 0.12 } } : { barMaxWidth: 28, itemStyle: { borderRadius: [4, 4, 4, 4] } }) }],
        }}
        style={{ height, cursor: onSelect ? "pointer" : undefined }}
        onEvents={onSelect ? { click: (event: { dataIndex: number }) => onSelect(event.dataIndex) } : undefined}
      />
    </div>
  );
}

/** Money in vs money out per month; `flow` shows one side only. Bars are major units for pixel scale only. */
type ForecastChartDay ={ date: string; expected: number; conservative: number; optimistic: number };
type ForecastChartObligation = { date: string; name: string; amount: string };

// Approximate chart coordinates (major units as numbers); exact amounts are rendered by the caller.
export function ForecastChart({ days, obligations, currency, label, compare }: {
  days: ForecastChartDay[]; obligations: ForecastChartObligation[]; currency: string; label: string;
  /** Optional second expected line, e.g. the real plan while a what-if scenario is shown. */
  compare?: { name: string; values: number[] };
}) {
  const brand = token("--color-brand", "#cbf26b"), muted = token("--color-muted-foreground", "#a3a39e"), border = token("--color-border", "#24262a");
  const expectedOn = new Map(days.map(day => [day.date, day.expected]));
  return <div role="img" aria-label={label}>
    <ReactECharts style={{ height: 260 }} option={{
      grid: { left: 8, right: 16, top: 24, bottom: 8, containLabel: true },
      tooltip: { trigger: "axis", renderMode: "richText", formatter: (items: { dataIndex: number }[]) => {
        const day = days[items[0]?.dataIndex];
        if (!day) return "";
        const due = obligations.filter(item => item.date === day.date).map(item => `\n${item.name}: ${item.amount}`).join("");
        return `${day.date}\nExpected ${currency} ${day.expected.toFixed(2)}\nConservative ${currency} ${day.conservative.toFixed(2)}${compare ? `\n${compare.name} ${currency} ${compare.values[items[0].dataIndex]?.toFixed(2)}` : ""}${due}`;
      } },
      xAxis: { type: "category", boundaryGap: false, data: days.map(day => day.date), axisLabel: { color: muted }, axisLine: { lineStyle: { color: border } } },
      yAxis: { type: "value", scale: true, axisLabel: { color: muted }, splitLine: { lineStyle: { color: border, type: "dashed" } } },
      series: [
        { name: "Conservative", type: "line", stack: "band", symbol: "none", lineStyle: { opacity: 0 }, data: days.map(day => day.conservative) },
        { name: "Range", type: "line", stack: "band", symbol: "none", lineStyle: { opacity: 0 }, areaStyle: { color: brand, opacity: 0.12 },
          data: days.map(day => day.optimistic - day.conservative) },
        { name: "Expected", type: "line", symbol: "none", lineStyle: { color: brand, width: 2.5 }, data: days.map(day => day.expected) },
        ...(compare ? [{ name: compare.name, type: "line", symbol: "none", lineStyle: { color: muted, width: 1.5, type: "dashed" }, data: compare.values }] : []),
        { name: "Obligations", type: "scatter", symbolSize: 9, itemStyle: { color: muted }, tooltip: { show: false },
          data: [...new Set(obligations.map(item => item.date))].filter(date => expectedOn.has(date)).map(date => [date, expectedOn.get(date)]) },
      ],
    }} />
  </div>;
}

// Lime, violet and coral lead, as in the app; the rest stay distinguishable in both themes.
const SERIES_COLORS = ["#a6cf3f", "#9b87f5", "#f2875f", "#7a8699", "#4fb3bf", "#d9a93a", "#d16ba5", "#5c9e31", "#b5651d", "#4b5bb5", "#c94f6d", "#2a6fdb"];

/** Parses a model-written ```chart block: any ECharts option object, or null when it is not one. */
export type Point = { date: string; value: bigint };

// Server-rendered SVG: no chart library or client JS. Numbers are used only for pixel scale.
export function Sparkline({ points, label, width = 120, height = 32, className = "text-brand", area = false }: { points: Point[]; label: string; width?: number; height?: number; className?: string; area?: boolean }) {
  if (points.length < 2) return <span className="text-xs text-muted-foreground">No trend yet</span>;
  const values = points.map(point => Number(point.value));
  const min = Math.min(...values), max = Math.max(...values), span = max - min || 1;
  const step = width / (points.length - 1);
  const path = values.map((value, index) => `${(index * step).toFixed(1)},${(height - 2 - ((value - min) / span) * (height - 4)).toFixed(1)}`).join(" ");
  return <svg role="img" aria-label={label} viewBox={`0 0 ${width} ${height}`} width={width} height={height} preserveAspectRatio={area ? "none" : undefined} className={`overflow-visible ${className}`}>
    {area && <polygon points={`0,${height} ${path} ${width},${height}`} fill="currentColor" fillOpacity={0.08} />}
    <polyline points={path} fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
  </svg>;
}

