};
const time = async (tx, sql) => {
  const t = [];
  for (let i = 0; i < 5; i++) {
    await tx`set local role authenticated`;
    const [r] = await tx.unsafe(`explain (analyze, format json) ${sql}`, [mine.id]);
    await tx`reset role`;
    const p = r["QUERY PLAN"][0]; t.push(p["Execution Time"] + p["Planning Time"]);
  }
