  await tx`create index on public.transactions (workspace_id, id)`;
  await tx`create index on public.transactions (workspace_id, posted_on desc, id desc)`;
  await tx`create index on public.balance_snapshots (workspace_id, id)`;
  await tx`analyze public.transactions`; await tx`analyze public.balance_snapshots`;
  for (const [name, sql] of Object.entries(queries)) results[name].indexed = await time(tx, sql);
  throw Object.assign(new Error("rollback"), { rollback: true });
}).catch(e => { if (!e.rollback) throw e; });
console.table(results);
const [check] = await db`select count(*)::int c from public.transactions where 'scale' = any(tags)`;
