// Mirrors 202610270001's workspace indexes into lib/schema.ts.
import fs from "node:fs";
const file = "lib/schema.ts";
let lines = fs.readFileSync(file, "utf8").split(/\r?\n/);
const crlf = fs.readFileSync(file, "utf8").includes("\r\n");
const wanted = {
  transactions: [`index("transactions_workspace_id").on(table.workspaceId, table.id)`, `index("transactions_workspace_posted").on(table.workspaceId, table.postedOn.desc(), table.id.desc())`],
  messages: [`index("messages_workspace").on(table.workspaceId)`],
  source_transactions: [`index("source_transactions_workspace_id").on(table.workspaceId, table.id)`],
  correction_events: [`index("correction_events_workspace").on(table.workspaceId)`],
  agent_tasks: [`index("agent_tasks_workspace").on(table.workspaceId)`],
  accounts: [`index("accounts_workspace").on(table.workspaceId, table.id)`],
  balance_snapshots: [`index("balance_snapshots_workspace_id").on(table.workspaceId, table.id)`],
  data_sources: [`index("data_sources_workspace").on(table.workspaceId)`],
  import_staging: [`index("import_staging_workspace").on(table.workspaceId)`],
  wealth_items: [`index("wealth_items_workspace").on(table.workspaceId)`],
  recurring_series_transactions: [`index("recurring_series_transactions_workspace").on(table.workspaceId)`],
  financial_assumptions: [`index("financial_assumptions_workspace").on(table.workspaceId)`],
  scenario_overrides: [`index("scenario_overrides_workspace").on(table.workspaceId)`],
  artifact_versions: [`index("artifact_versions_workspace").on(table.workspaceId)`],
  transaction_splits: [`index("transaction_splits_workspace").on(table.workspaceId)`],
  bank_connection_accounts: [`index("bank_connection_accounts_workspace").on(table.workspaceId)`],
  scenarios: [`index("scenarios_workspace").on(table.workspaceId)`],
  transaction_link_fees: [`index("transaction_link_fees_workspace").on(table.workspaceId)`],
  chat_steers: [`index("chat_steers_workspace").on(table.workspaceId)`],
  saved_analyses: [`index("saved_analyses_workspace").on(table.workspaceId)`],
  goal_allocations: [`index("goal_allocations_workspace").on(table.workspaceId)`],
  forecast_runs: [`index("forecast_runs_workspace").on(table.workspaceId)`],
};
for (const [name, indexes] of Object.entries(wanted)) {
  const start = lines.findIndex(line => line.includes(`pgTable("${name}", {`));
  if (start < 0) throw new Error(`no table ${name}`);
  let end = start + 1;
  while (!/^\}(, \((table|t)\) => \[|\);)/.test(lines[end])) end++;
  const param = lines[end].match(/\((table|t)\) =>/)?.[1] ?? "table";
  const entries = indexes.map(entry => `  ${entry.replaceAll("table.", `${param}.`)},`);
  if (lines[end].startsWith("});")) lines.splice(end, 1, `}, (${param}) => [`, ...entries, "]);");
  else lines.splice(end + 1, 0, ...entries);
}
fs.writeFileSync(file, lines.join(crlf ? "\r\n" : "\n"));
console.log("ok");

