// Click-to-ready for rail navigations after resting the pointer on the link for different times.
import { chromium } from "@playwright/test";
const BASE = process.env.BASE ?? "http://localhost:3217";
const browser = await chromium.launch();
const page = await (await browser.newContext({ storageState: "e2e/.auth.json", viewport: { width: 1440, height: 900 } })).newPage();
const out = {};
for (const path of ["/plan", "/money/transactions", "/money/accounts"]) for (const rest of [0, 150, 300, 600, 1200]) {
  const times = [];
  for (let i = 0; i < 5; i++) {
    await page.goto(BASE + "/"); await page.waitForFunction(() => document.querySelector("main h1")?.textContent === "Overview" && !document.querySelector('main [aria-busy="true"]'));
    await page.mouse.move(700, 450); await page.waitForTimeout(300);
    const sel = `nav[aria-label="Main"] a[href="${path}"]`;
    if (rest) { await page.hover(sel); await page.waitForTimeout(rest); }
    const ms = await page.evaluate(({ sel, path }) => new Promise(resolve => {
      const old = document.querySelector("main"), t0 = performance.now();
      document.querySelector(sel).click();
      const tick = () => { const m = document.querySelector("main"); if (location.pathname === path && m && m !== old && !m.matches('[aria-busy="true"]') && m.querySelector("h1") && !m.querySelector('[aria-busy="true"]')) resolve(Math.round(performance.now() - t0)); else requestAnimationFrame(tick); };
      tick();
    }), { sel, path });
    times.push(ms);
  }
  times.sort((a, b) => a - b);
  (out[path] ??= {})[`rest ${rest} ms`] = times[2];
}
console.table(out);
await browser.close();

