await p.addInitScript(()=>{window.__t={};new MutationObserver(()=>{const now=performance.now();if(!window.__t.cashflow&&document.querySelector('#cash-flow'))window.__t.cashflow=now;if(!window.__t.pulse&&document.querySelector('#cash-flow .animate-pulse'))window.__t.pulse=now;if(!window.__t.canvas&&document.querySelector('#cash-flow canvas'))window.__t.canvas=now;if(!window.__t.ready&&document.querySelector('main h1')&&!document.querySelector('main [aria-busy=\"true\"]'))window.__t.ready=now}).observe(document,{subtree:true,childList:true,attributes:true})});
await p.goto('http://localhost:3217/');await p.waitForSelector('#cash-flow canvas');
for(let i=0;i<3;i++){await p.goto('about:blank');await p.goto('http://localhost:3217/');await p.waitForSelector('#cash-flow canvas');await p.waitForTimeout(300);
console.log(await p.evaluate(()=>{const n=performance.getEntriesByType('navigation')[0];const js=performance.getEntriesByType('resource').filter(e=>e.name.endsWith('.js'));const r=x=>Math.round(x);return {htmlEnd:r(n.responseEnd),dcl:r(n.domContentLoadedEventStart),cashflowSection:r(__t.cashflow),pulsePlaceholder:r(__t.pulse),allSectionsReady:r(__t.ready),lastChunkStart:r(Math.max(...js.map(e=>e.startTime))),lastChunkEnd:r(Math.max(...js.map(e=>e.responseEnd))),canvas:r(__t.canvas)}}));}
await b.close()})()"
